  // change what existing subscriptions or an unmount flush persist.
  useLayoutEffect(() => {
    scopeRef.current = scope;
    persistRef.current = persistLocally;
    retainedRef.current = retainedSnapshots;
    restoredDraftRef.current = restoredDraft;
