    const stored = saveFillDraft(
      current,
      snapshotAll(),
      retainedRef.current,
      storedDraftRef.current,
    );
    if (stored) storedDraftRef.current = true;
  }, [snapshotAll]);

  /**
   * The session SHAPE changed (a form was added or removed) or a store
   * (un)registered — persist now. The debounce cannot cover this: on an
   * update React runs the previous effect's cleanup BEFORE the new
   * sections' StoreRegistrars register, so that flush would write a
   * snapshot missing the just-added forms and silently shrink the stored
   * draft (the Resume path re-adds drafted forms exactly this way).
   * Gated on `dirty`, because an untouched session has nothing of the
   * clinician's to write.
   */
  useEffect(() => {
    if (!scopeKey || !persistLocally || !dirty) return;
    persistNow();
  }, [
    scopeKey,
    persistLocally,
    dirty,
    storesVersion,
    retainedSnapshots,
    persistNow,
  ]);

  // Not gated on `scopeKey`/`persistLocally`: dirty tracking is what arms
  // the unsaved-changes prompt and the Draft chip, and a session resuming
  // a SERVER draft needs both even though it writes no local draft.
  // `persistNow` is the thing that stands down, not the subscription.
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout> | undefined;

    const flush = () => {
      if (timer === undefined) return;
      clearTimeout(timer);
      timer = undefined;
      persistNow();
    };

    // Per-form signature cache, keyed by form.key. A keystroke only ever
    // changes the ONE store that fired, so comparing just that form's own
    // cached entry is sufficient — no other form's signature could have
    // changed, so there is nothing to gain from joining them into a
    // session-wide value.
    //
    // Rebuilt from scratch on every (re)run of this effect — a form
    // add/remove or a store (un)registration bumps `storesVersion`, which
    // is a dependency below — by iterating the CURRENT `forms`/`getStore`.
    // A form no longer in that iteration simply never gets an entry, so a
    // removed form's stale signature can never survive to be compared
    // against again.
    //
    // Whatever is already in the stores when this is built is the
    // baseline, not an edit — this is where the structured widgets'
    // prefetched server rows sit.
    const formSignatures = new Map<string, string>();
    for (const form of forms) {
      const store = getStore(form.key);
      if (!store) continue;
      registeredStores.current.set(form.key, store);
      formSignatures.set(form.key, formSignature(form, store));
    }

    // One shared debounce across every form of the session — the draft is
    // one localStorage entry, so one timer is all it can honour.
    const unsubscribers = forms.flatMap((form) => {
      const store = getStore(form.key);
      if (!store) return [];
      return [
        store.sub(responsesAtom, () => {
          if (finishedRef.current) return;
          // Compare this form's clinician input only. Prefill values are
          // normalized against draft_context; file metadata still marks
          // unsaved work even though the attachment cannot be drafted.
          const signature = formSignature(form, store);
          if (formSignatures.get(form.key) === signature) return;
          formSignatures.set(form.key, signature);
          setDirty(true);
          clearTimeout(timer);
          timer = setTimeout(() => {
            timer = undefined;
            persistNow();
          }, AUTOSAVE_DEBOUNCE_MS);
        }),
      ];
    });

    // pagehide covers reload/close/bfcache; unmount covers in-app nav.
    window.addEventListener("pagehide", flush);
    return () => {
      window.removeEventListener("pagehide", flush);
      flush();
      for (const unsubscribe of unsubscribers) unsubscribe();
    };
    // storesVersion re-runs the subscription when a form (un)registers.
  }, [storesVersion, forms, getStore, persistNow]);

  /** Successful submit: drop the stored draft, stop all further saves,
   *  and clear the dirty flag SYNCHRONOUSLY (flushSync) — the success
   *  handler navigates right after this, and `useNavigationPrompt` must
   *  already see a pristine page or it blocks the redirect.
   *
   *  The clear runs off `scope`, not off whether this session PERSISTED
   *  locally: a server-draft session shares its key with the plain mount,
   *  and a local draft left behind there would prompt Resume with answers
   *  this submit already filed. */
  const finishDraft = useCallback(() => {
    finishedRef.current = true;
    const current = scopeRef.current;
    if (current) clearFillDraft(current);
    flushSync(() => {
      setDirty(false);
      setRestoreDismissed(true);
    });
  }, []);

  const discardRestoredDraft = useCallback(() => {
    const current = scopeRef.current;
    if (current) clearFillDraft(current);
    // Discard drops the STORED draft — never what is on screen. The draft
    // only ever reaches the stores through Resume, so while the bar shows
    // they hold nothing but this session's own work: prefetched clinical
    // rows and whatever the clinician typed while ignoring the prompt.
    // Resetting them would destroy exactly the un-persisted work the
    // prompt gate protects.
    //
    // Persistence was standing down while the prompt was pending — flip
    // the gate synchronously (the ref updates only after the next commit)
    // and write now, so anything typed in the meantime becomes a fresh
    // draft of its own instead of living un-persisted until the next
    // keystroke. An untouched session stores nothing, and the key it would
    // otherwise clear is already gone.
    restorePendingRef.current = false;
    setRestoreDismissed(true);
    persistNow();
  }, [persistNow]);

  const dismissRestoreBar = useCallback(() => {
    restorePendingRef.current = false;
    setRestoreDismissed(true);
    persistNow();
  }, [persistNow]);

  /** Apply the restored draft — from the overview or restore prompt. The
   *  primary form's snapshot lands in the live store through the shared
   *  overlay rule; every other snapshot goes back to the host, which
   *  re-adds those questionnaires seeded from their snapshots. */
  const resumeRestoredDraft = useCallback(() => {
    const draft = restoredDraftRef.current;
    if (!draft || restoredAppliedRef.current) return;
    const primary = forms.find((form) => form.isPrimary);
    const store = primary && getStore(primary.key);
    // Automatic restoration can run during mount. Wait for registration
    // instead of dismissing the draft before its answers reach the form.
    if (!primary || !store) return;
    restoredAppliedRef.current = true;
    const addedSnapshots: DraftFormSnapshot[] = [];
    for (const snapshot of draft.forms) {
      if (snapshot.questionnaireId === primary.key) {
        store.set(
          responsesAtom,
          preserveExcludedStructured(
            store.get(responsesAtom),
            mergeDraftIntoSeed(
              primary.questionnaire.questions,
              snapshot.responses,
            ),
          ),
        );
        continue;
      }
      addedSnapshots.push(snapshot);
    }
    if (addedSnapshots.length > 0) onResumeAddedForms(addedSnapshots);
    setDirty(true);
    setRestoreDismissed(true);
  }, [forms, getStore, onResumeAddedForms]);

  useEffect(() => {
    if (resumeAutomatically) resumeRestoredDraft();
  }, [resumeAutomatically, storesVersion, resumeRestoredDraft]);

  return {
    /** Any edit since mount — drives the Draft chip. A merely-detected
     *  draft is NOT dirty; the chip lights only after Resume or an edit. */
    dirty,
    restoredDraft: restoreDismissed ? undefined : restoredDraft,
    discardRestoredDraft,
    dismissRestoreBar,
    resumeRestoredDraft,
    /** For the submit-success path: the draft served its purpose. */
    finishDraft,
  };
}
import { useQueryClient } from "@tanstack/react-query";
import { useCallback, useEffect, useRef, useState } from "react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { responsesAtom } from "@/components/QuestionnaireV2/form/engine/store";
import { questionnaireKeys } from "@/components/QuestionnaireV2/queryKeys";

import query from "@/Utils/request/query";
import type { QuestionnaireResponse } from "@/types/questionnaire/form";
import type { QuestionnaireRead } from "@/types/questionnaire/questionnaire";
import questionnaireApi from "@/types/questionnaire/questionnaireApi";

import type { FormStore } from "./StoreRegistrar";
import type { DraftFormSnapshot } from "./draft/fillDraftStore";
import {
  mergeDraftIntoSeed,
  preserveExcludedStructured,
} from "./draft/fillDraftStore";
import type { FillFormEntry } from "./formSession";

interface UseFillSessionFormsArgs {
  /** The route-mounted questionnaire — seeds the session's one PRIMARY
   *  form. Only read once (the initial `useState` seed); later identity
   *  changes have no effect. */
  questionnaire: QuestionnaireRead;
  /** Resumed server draft responses, seeded into the primary form at
   *  creation only. */
  serverDraftResponses?: Record<string, QuestionnaireResponse>;
  getStore: (key: string) => FormStore | undefined;
}

/**
 * The fill session's form list plus everything that mutates it: adding a
 * questionnaire (by hand or via a drafted resume), removing one, and the
 * retained-snapshot bookkeeping for forms the draft is still carrying
 * without a live store (a resume whose re-fetch failed).
 */
export function useFillSessionForms({
  questionnaire,
  serverDraftResponses,
  getStore,
}: UseFillSessionFormsArgs) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();

  // The session: the route-mounted questionnaire plus anything added to
  // the same submission. Each entry owns one provider and one store.
  const [forms, setForms] = useState<FillFormEntry[]>(() => [
    {
      key: questionnaire.id,
      questionnaire,
      isPrimary: true,
      initialResponses: serverDraftResponses,
    },
  ]);

  const addQuestionnaire = useCallback(
    (
      added: QuestionnaireRead,
      initialResponses?: Record<string, QuestionnaireResponse>,
    ) => {
      setForms((previous) =>
        previous.some((form) => form.key === added.id)
          ? previous
          : [
              ...previous,
              {
                key: added.id,
                questionnaire: added,
                isPrimary: false,
                initialResponses,
              },
            ],
      );
    },
    [],
  );
  const removeForm = useCallback((key: string) => {
    setForms((previous) =>
      previous.filter((form) => form.key !== key || form.isPrimary),
    );
  }, []);

  // Snapshots that belong to the draft but are not (yet) live forms. They
  // stay in the persisted draft (see `saveFillDraft`'s `retained`) — the
  // ways a resume can fail are NOT the same: a version bump means the
  // answers can no longer be trusted onto the new tree and dropping them
  // is correct, while a network error means try again later, and
  // destroying the clinician's only copy over it is not.
  const [retainedSnapshots, setRetainedSnapshots] = useState<
    DraftFormSnapshot[]
  >([]);
  const dropRetainedSnapshot = useCallback((questionnaireId: string) => {
    setRetainedSnapshots((previous) =>
      previous.filter((entry) => entry.questionnaireId !== questionnaireId),
    );
  }, []);

  // Read by resume callbacks that must see the CURRENT session without
  // re-creating themselves per forms change. Effect-synced, which is
  // enough: every reader is an event-handler-initiated async path that
  // runs strictly after the commit that changed `forms`.
  const formsRef = useRef(forms);
  useEffect(() => {
    formsRef.current = forms;
  }, [forms]);

  /** Resume non-primary snapshots. Each snapshot is retained before refetch
   *  so autosave cannot erase it while it is not yet attached to a live form;
   *  refetch success mounts or merges it, version drift drops it, and fetch
   *  failure keeps it retained for a later retry. */
  const onResumeAddedForms = useCallback(
    (snapshots: DraftFormSnapshot[]) => {
      setRetainedSnapshots((previous) => {
        const seen = new Set(previous.map((entry) => entry.questionnaireId));
        return [
          ...previous,
          ...snapshots.filter(
            (snapshot) => !seen.has(snapshot.questionnaireId),
          ),
        ];
      });
      void (async () => {
        for (const snapshot of snapshots) {
          // Already in the session (the clinician added it by hand before
          // pressing Resume): apply the snapshot to the live store the
          // same way the primary form's resume overlay does — dropping it
          // silently would erase the drafted answers from the stored
          // draft on the very next persist.
          const existing = formsRef.current.find(
            (form) => form.key === snapshot.questionnaireId,
          );
          if (existing) {
            if (
              String(existing.questionnaire.version) !==
              snapshot.questionnaireVersion
            ) {
              dropRetainedSnapshot(snapshot.questionnaireId);
              toast.warning(
                t("fill_draft_form_dropped", {
                  title: existing.questionnaire.title,
                }),
              );
              continue;
            }
            const store = getStore(existing.key);
            if (store) {
              store.set(
                responsesAtom,
                preserveExcludedStructured(
                  store.get(responsesAtom),
                  mergeDraftIntoSeed(
                    existing.questionnaire.questions,
                    snapshot.responses,
                  ),
                ),
              );
            }
            dropRetainedSnapshot(snapshot.questionnaireId);
            continue;
          }
          try {
            const fetched = await queryClient.fetchQuery({
              queryKey: questionnaireKeys.detail(snapshot.questionnaireId),
              queryFn: query(questionnaireApi.get, {
                pathParams: { id: snapshot.questionnaireId },
              }),
            });
            if (String(fetched.version) !== snapshot.questionnaireVersion) {
              dropRetainedSnapshot(snapshot.questionnaireId);
              toast.warning(
                t("fill_draft_form_dropped", { title: fetched.title }),
              );
              continue;
            }
            addQuestionnaire(
              fetched,
              mergeDraftIntoSeed(fetched.questions, snapshot.responses),
            );
            dropRetainedSnapshot(snapshot.questionnaireId);
          } catch {
            // Treat fetch failures as transient: keep the snapshot in the stored
            // draft so the next persist cannot erase it. The stored title is
            // the best available label; fall back to the id when absent.
            toast.warning(
              t("fill_draft_form_unavailable", {
                title: snapshot.title ?? snapshot.questionnaireId,
              }),
            );
          }
        }
      })();
    },
    [queryClient, addQuestionnaire, getStore, dropRetainedSnapshot, t],
  );

  /** The in-session picker's add. When the picked questionnaire matches a
   *  RETAINED snapshot (its resume re-fetch failed earlier), that snapshot
   *  IS the drafted form — seed from it instead of mounting empty, which
   *  would displace the snapshot from the stored draft on the next
   *  persist. A version drift drops it with the same toast as resume. */
  const addQuestionnaireFromPicker = useCallback(
    (selected: QuestionnaireRead) => {
      const snapshot = retainedSnapshots.find(
        (entry) => entry.questionnaireId === selected.id,
      );
      if (!snapshot) {
        addQuestionnaire(selected);
        return;
      }
      dropRetainedSnapshot(selected.id);
      if (String(selected.version) !== snapshot.questionnaireVersion) {
        toast.warning(t("fill_draft_form_dropped", { title: selected.title }));
        addQuestionnaire(selected);
        return;
      }
      addQuestionnaire(
        selected,
        mergeDraftIntoSeed(selected.questions, snapshot.responses),
      );
    },
    [retainedSnapshots, addQuestionnaire, dropRetainedSnapshot, t],
  );

  return {
    forms,
    addQuestionnaire,
    removeForm,
    retainedSnapshots,
    onResumeAddedForms,
    addQuestionnaireFromPicker,
  };
}
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";

import type { ServerValidationError } from "./submit/mapBatchErrors";

/** Page-level surface for batch sub-request failures (per-question
 *  failures additionally land on their blocks via errorsAtom). */
export function ServerErrorsPanel({
  errors,
}: {
  errors: ServerValidationError[];
}) {
  const { t } = useTranslation();
  if (errors.length === 0) return null;
  return (
    <Alert variant="destructive" className="mx-auto mb-4 w-full max-w-3xl">
      <AlertTitle>{t("questionnaire_submission_failed")}</AlertTitle>
      <AlertDescription>
        <ul className="list-disc space-y-1 pl-4">
          {errors.map((error, index) => (
            <li key={`${error.reference_id}-${index}`}>{error.message}</li>
          ))}
        </ul>
      </AlertDescription>
    </Alert>
  );
}

