import careConfig from "@careConfig";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { AlertCircle, ChevronDown, ImageIcon, Printer } from "lucide-react";
import { ReactNode, useState } from "react";
import { useTranslation } from "react-i18next";
import { formatPhoneNumberIntl } from "react-phone-number-input";
import { toast } from "sonner";

import { cn } from "@/lib/utils";

import CareIcon from "@/CAREUI/icons/CareIcon";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Markdown } from "@/components/ui/markdown";
import { Skeleton } from "@/components/ui/skeleton";
import { TooltipComponent } from "@/components/ui/tooltip";

import { Avatar } from "@/components/Common/Avatar";
import AvatarEditModal from "@/components/Common/AvatarEditModal";
import ContactLink from "@/components/Common/ContactLink";
import Loading from "@/components/Common/Loading";
import ErrorPage from "@/components/ErrorPages/DefaultErrorPage";
import FacilityDeleteDialog from "@/components/Facility/FacilityDeleteDialog";
import PrintTemplateSheet from "@/components/Facility/PrintTemplateSheet";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

import useAuthUser from "@/hooks/useAuthUser";

import { getPermissions } from "@/common/Permissions";

import { PLUGIN_Component } from "@/PluginEngine";
import mutate from "@/Utils/request/mutate";
import query from "@/Utils/request/query";
import { usePermissions } from "@/context/PermissionContext";
import { FeatureBadge } from "@/pages/Facility/Utils";
import { FacilitySettingsOverview } from "@/pages/Facility/settings/general/FacilitySettingsOverview";
import EditFacilitySheet from "@/pages/Organization/components/EditFacilitySheet";
import { FACILITY_FEATURE_TYPES } from "@/types/facility/facility";
import facilityApi from "@/types/facility/facilityApi";
import { renderGeoOrganizations } from "@/types/organization/organization";

import { FacilityMapsLink } from "./FacilityMapLink";

interface FacilityHomeProps {
  facilityId: string;
  appearance?: "default" | "settings";
  renderSettingsActions?: (disabled: boolean) => ReactNode;
}

const settingsButtonClassName =
  "h-12 border-neutral-400 text-sm text-neutral-950 shadow-md hover:bg-neutral-200/75 focus-visible:ring-0 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-500 md:h-10 [&_svg]:size-5";

export const FacilityHome = ({
  facilityId,
  appearance = "default",
  renderSettingsActions,
}: FacilityHomeProps) => {
  const isSettings = appearance === "settings";
  const { t } = useTranslation();
  const user = useAuthUser();
  const [editCoverImage, setEditCoverImage] = useState(false);
  const queryClient = useQueryClient();
  const { hasPermission } = usePermissions();

  const {
    data: facilityData,
    isLoading,
    isError,
    isFetching,
    refetch,
  } = useQuery({
    queryKey: ["facility", facilityId],
    queryFn: query(facilityApi.get, {
      pathParams: { facilityId },
    }),
  });

  const { canUpdateFacility } = getPermissions(
    hasPermission,
    facilityData?.root_org_permissions ?? [],
  );
  const { mutateAsync: deleteAvatar } = useMutation({
    mutationFn: mutate(facilityApi.deleteCoverImage, {
      pathParams: { facilityId },
    }),
    onSuccess: () => {
      toast.success(t("cover_image_deleted"));
      queryClient.invalidateQueries({
        queryKey: ["facility", facilityId],
      });
      setEditCoverImage(false);
    },
  });

  const { mutateAsync: uploadCoverImage } = useMutation({
    mutationFn: mutate(facilityApi.uploadCoverImage, {
      pathParams: { facilityId },
    }),
    onSuccess: () => {
      setEditCoverImage(false);
      queryClient.invalidateQueries({
        queryKey: ["facility", facilityId],
      });
      toast.success(t("cover_image_updated"));
    },
  });

  const handleCoverImageUpload = async (
    file: File,
    onSuccess: () => void,
    onError: () => void,
  ) => {
    try {
      const formData = new FormData();
      formData.append("cover_image", file);
      await uploadCoverImage(formData);
      onSuccess();
    } catch {
      onError();
    }
  };
  const handleCoverImageDelete = async (
    onSuccess: () => void,
    onError: () => void,
  ) => {
    try {
      await deleteAvatar();
      onSuccess();
    } catch {
      onError();
    }
  };

  if (isLoading) {
    return isSettings ? (
      <div role="status" className="space-y-6">
        <span className="sr-only">{t("loading")}</span>
        <div className="flex items-center gap-4 border-b border-neutral-200 pb-6">
          <Skeleton className="size-16 rounded-[10px]" />
          <div className="space-y-2">
            <Skeleton className="h-7 w-56 max-w-[60vw]" />
            <Skeleton className="h-4 w-32" />
          </div>
        </div>
        <div className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_20rem]">
          <Skeleton className="h-64 rounded-[10px]" />
          <Skeleton className="h-48 rounded-[10px]" />
        </div>
      </div>
    ) : (
      <Loading />
    );
  }

  const facilityError = (
    <Alert variant="destructive" className="mb-4">
      <AlertCircle />
      <AlertDescription>
        <p>
          {t(facilityData ? "facility_refresh_error" : "facility_load_error")}
        </p>
        <Button
          variant="outline"
          className={cn("mt-3", settingsButtonClassName)}
          disabled={isFetching}
          onClick={() => void refetch()}
        >
          {t("try_again")}
        </Button>
      </AlertDescription>
    </Alert>
  );

  if (isSettings && !facilityData) {
    return facilityError;
  }

  const coverImageHint = (
    <>
      {t("max_size_for_image_uploaded_should_be", {
        maxSize: `${careConfig.imageUploadMaxSizeInMB}MB`,
      })}
      <br />
      {t("allowed_formats_are", { formats: "jpg, png, jpeg" })}{" "}
      {t("recommended_aspect_ratio_for", { aspectRatio: "16:9" })}
    </>
  );

  if (!facilityData) {
    return <ErrorPage />;
  }

  const coverImageDialog = (
    <AvatarEditModal
      title={t("edit_cover_photo")}
      open={editCoverImage}
      imageUrl={facilityData?.read_cover_image_url}
      handleUpload={handleCoverImageUpload}
      handleDelete={handleCoverImageDelete}
      onOpenChange={(open) => setEditCoverImage(open)}
      hint={coverImageHint}
      aspectRatio={16 / 9}
    />
  );
  const editAction = (
    <EditFacilitySheet
      facilityId={facilityId}
      trigger={
        <Button
          className={cn(
            "cursor-pointer font-semibold",
            isSettings && settingsButtonClassName,
            isSettings &&
              "col-span-2 border-emerald-950 bg-emerald-800 text-white hover:bg-emerald-900 hover:text-white sm:col-span-1",
          )}
          variant="outline"
          size="sm"
        >
          <CareIcon icon="l-pen" />
          {t("edit_facility_details")}
        </Button>
      }
    />
  );
  const configurationAction = (
    <DropdownMenu modal={false}>
      <DropdownMenuTrigger asChild>
        <Button
          variant="outline"
          size="sm"
          className={cn(
            "cursor-pointer font-semibold",
            isSettings && settingsButtonClassName,
          )}
          aria-label={isSettings ? t("configurations") : "More Options"}
          type="button"
        >
          {t("configurations")}
          <ChevronDown className="size-4" />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent
        align="end"
        className={cn(
          "w-full min-w-48",
          isSettings && "rounded-lg border-neutral-200 shadow-md",
        )}
      >
        <DropdownMenuGroup className="flex flex-col gap-1">
          <PrintTemplateSheet
            facility={facilityData}
            trigger={
              <button
                type="button"
                className={cn(
                  "hover:bg-gray-100 hover:text-gray-900 flex w-full cursor-pointer items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-hidden select-none [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
                  isSettings &&
                    "min-h-12 text-neutral-950 hover:bg-neutral-100 focus-visible:outline-2 focus-visible:outline-indigo-500 md:min-h-10",
                )}
              >
                <Printer className="size-4 text-gray-500" />
                {t("print_templates")}
              </button>
            }
          />
          <PLUGIN_Component
            __name="FacilityHomeActions"
            facility={facilityData}
            className="flex justify-start items-center border border-gray-200 rounded-md p-2 shadow-sm"
          />
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
  const facilityActions = canUpdateFacility ? (
    <>
      {isSettings && editAction}
      {isSettings && (
        <Button
          variant="outline"
          className={settingsButtonClassName}
          onClick={() => setEditCoverImage(true)}
        >
          <ImageIcon className="size-5" />
          {t("edit_cover_photo")}
        </Button>
      )}
      {configurationAction}
      {!isSettings && editAction}
    </>
  ) : null;

  if (isSettings) {
    return (
      <>
        {coverImageDialog}
        {isError && facilityError}
        <FacilitySettingsOverview
          facility={facilityData}
          actions={facilityActions}
          settingsActions={renderSettingsActions?.(isError)}
          canDelete={user.is_superuser}
        />
      </>
    );
  }

  return (
    <div>
      {coverImageDialog}
      <div className="container mx-auto pt-2">
        <div className="mx-auto max-w-3xl space-y-6">
          <Card className="border-none bg-transparent shadow-none">
            <div className="group rounded-2xl relative h-64 w-full bg-linear-to-br from-emerald-400 via-emerald-500 to-emerald-600">
              {facilityData?.read_cover_image_url ? (
                <>
                  <img
                    src={facilityData.read_cover_image_url}
                    alt={facilityData?.name}
                    className="h-full w-full object-cover rounded-2xl"
                  />
                  <div className="absolute rounded-2xl inset-0 bg-linear-to-t from-black/60 via-black/30 to-transparent transition-opacity group-hover:opacity-70" />
                </>
              ) : (
                <div className="relative rounded-2xl  h-full w-full bg-[radial-gradient(circle_at_50%_120%,rgba(255,255,255,0.2),transparent)]" />
              )}
              <div className="absolute bottom-0 left-0 translate-x-0 translate-y-1/3">
                <div className="sm:px-4 px-8 inline-flex rounded-xl">
                  <Avatar
                    name={facilityData.name}
                    className="size-20 md:size-24 rounded-xl border-4 border-white shadow-lg"
                  />
                </div>
              </div>

              <div className="absolute bottom-0 left-0 translate-x-0 ml-32">
                <div className="flex flex-wrap items-center gap-4 md:gap-6">
                  <div className="flex-1 min-w-0 mb-2">
                    <div className="text-white">
                      <TooltipComponent content={facilityData?.name}>
                        <h1 className="text-lg sm:text-sm md:text-2xl lg:text-3xl font-bold">
                          {facilityData?.name}
                        </h1>
                      </TooltipComponent>
                      <TooltipComponent
                        content={facilityData?.facility_type}
                        side="right"
                        align="center"
                        sideOffset={4}
                      >
                        <h2 className="text-xs sm:text-sm md:text-base lg:text-base text-white/70 inline-block">
                          {facilityData?.facility_type}
                        </h2>
                      </TooltipComponent>
                    </div>
                  </div>
                </div>
              </div>
              <div className="absolute right-0 bottom-0 p-1 text-white [@media(max-width:55rem)]:top-0">
                {canUpdateFacility && (
                  <Button
                    variant="link"
                    onClick={() => setEditCoverImage(true)}
                    aria-label={t("edit_cover_photo")}
                    size="sm"
                  >
                    <CareIcon
                      icon="l-pen"
                      className="text-white"
                      aria-hidden="true"
                    />
                    <span className="underline text-white">
                      {t("edit_cover_photo")}
                    </span>
                  </Button>
                )}
              </div>
            </div>

            <div className="flex justify-end max-sm:flex-col-reverse flex-wrap sm:gap-2">
              {canUpdateFacility && (
                <div className="flex gap-1 max-sm:flex-col mt-10 sm:mt-4">
                  {facilityActions}
                </div>
              )}
            </div>

            <div className="mt-4 space-y-4">
              <div className="flex flex-col [@media(min-width:60rem)]:flex-row gap-3">
