          )}
          variant="outline"
          size="sm"
        >
          <CareIcon icon="l-pen" />
          {t("edit_facility_details")}
        </Button>
      }
    />
  );
  const configurationAction = (
    <DropdownMenu modal={false}>
      <DropdownMenuTrigger asChild>
        <Button
          variant="outline"
          size="sm"
