import { CombinedDatePicker } from "@/components/ui/combined-date-picker";

import { RendererInputProps } from "@/components/QuestionnaireV2/form/engine/questionTypeRegistry";
import { useQuestionResponse } from "@/components/QuestionnaireV2/form/engine/store";

import { replaceEntryAt } from "./withEntryAt";

export function DateInput({
  question,
  disabled,
  labelId,
  valueIndex,
}: RendererInputProps) {
  const [response, updateResponse] = useQuestionResponse(question.id);
  // Discriminant check instead of a cast — a mismatched stored value (e.g. a
  // seeded string from answer_option) renders empty instead of crashing.
  const entry = response?.values[valueIndex ?? 0];
  const value = entry?.type === "date" ? entry.value : undefined;

  const handleChange = (date: Date | undefined) => {
    updateResponse({
      values: replaceEntryAt(
        response?.values,
        valueIndex,
        { type: "date", value: date },
        date === undefined,
      ),
    });
  };

  return (
    // The picker's trigger button takes no id/aria props (ui/ primitives
    // stay unmodified), so the question association rides on a named
    // group — without it every date question announces as an identical
    // bare "Pick a date" stop.
    <div
      role="group"
      aria-labelledby={labelId}
      aria-required={question.required || undefined}
    >
      <CombinedDatePicker
        value={value}
        onChange={handleChange}
        disabled={disabled}
        buttonClassName="border-gray-300 shadow-none"
      />
    </div>
  );
}
import { DatePicker } from "@/components/ui/date-picker";
import { Input } from "@/components/ui/input";

import { RendererInputProps } from "@/components/QuestionnaireV2/form/engine/questionTypeRegistry";
import { useQuestionResponse } from "@/components/QuestionnaireV2/form/engine/store";

import { replaceEntryAt } from "./withEntryAt";

function formatTime(date: Date | undefined) {
  if (!date) return "";
  return `${date.getHours().toString().padStart(2, "0")}:${date
    .getMinutes()
    .toString()
    .padStart(2, "0")}`;
}

export function DateTimeQuestionInput({
  question,
  disabled,
  labelId,
  valueIndex,
}: RendererInputProps) {
  const [response, updateResponse] = useQuestionResponse(question.id);
  // Discriminant check instead of a cast — a mismatched stored value (e.g. a
  // seeded string from answer_option) would otherwise reach formatTime and
  // crash on date.getHours() during render.
  const entry = response?.values[valueIndex ?? 0];
  const value = entry?.type === "dateTime" ? entry.value : undefined;

  const writeValue = (date: Date) => {
    updateResponse({
      values: replaceEntryAt(response?.values, valueIndex, {
        type: "dateTime",
        value: date,
      }),
    });
  };

  const handleDateChange = (date: Date | undefined) => {
    if (!date) return;
    const next = new Date(date);
    if (value) {
      next.setHours(value.getHours());
      next.setMinutes(value.getMinutes());
    }
    writeValue(next);
  };

  const handleTimeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const [hours, minutes] = e.target.value.split(":").map(Number);
    if (isNaN(hours) || isNaN(minutes)) return;

    // Fresh instance — never mutate the stored Date in place.
    const next = value ? new Date(value) : new Date();
    next.setHours(hours);
    next.setMinutes(minutes);

    writeValue(next);
  };

  return (
    // Named group for the same reason as DateInput: the picker trigger
    // takes no id/aria props, and the bare time input would otherwise
    // reach screen readers nameless.
    <div
      role="group"
      aria-labelledby={labelId}
      aria-required={question.required || undefined}
      className="flex flex-col sm:flex-row gap-2"
    >
      <DatePicker
        date={value}
        onChange={handleDateChange}
        disablePicker={disabled}
        className="flex-1 border-gray-300 shadow-none"
      />
      <Input
        type="time"
        aria-labelledby={labelId}
        className="h-9 sm:w-[150px]"
        value={formatTime(value)}
        onChange={handleTimeChange}
        disabled={disabled || !value}
      />
    </div>
  );
}
import {
  ArrowDown,
  ArrowUp,
  Copy,
  EyeOff,
  Plus,
  Split,
  Trash2,
  TriangleAlert,
} from "lucide-react";
import { Dispatch, createContext, useContext, useEffect, useMemo } from "react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { BuilderAction } from "@/components/QuestionnaireV2/builder/builderReducer";
import {
  FormChrome,
  QuestionShellProps,
} from "@/components/QuestionnaireV2/form/chrome";
import { QuestionnaireFormCanvas } from "@/components/QuestionnaireV2/form/FormCanvas";

import { Question } from "@/types/questionnaire/question";

import { questionsByLinkId, shortConditionSummary } from "./conditionSummary";

interface StudioCanvasContextValue {
  editing: boolean;
  selectedId: string | null;
  onSelectQuestion: (id: string) => void;
  dispatch: Dispatch<BuilderAction>;
  /** link_id → question, one build per tree change — the logic chips
   *  resolve enable_when targets from it, per block, on every render. */
  conditionTargets: ReadonlyMap<string, Question>;
  /** question id → save-rule i18n key, from findInvalidQuestions. */
  issueKeysByQuestionId: ReadonlyMap<string, string>;
}

const StudioCanvasContext = createContext<StudioCanvasContextValue | null>(
  null,
);

function useStudioCanvas(): StudioCanvasContextValue {
  const context = useContext(StudioCanvasContext);
  if (!context) {
    throw new Error("Studio chrome rendered outside StudioCanvas");
  }
  return context;
}

/**
 * The selection chrome injected into the form renderer's decoration seam.
 * Module-level components (never recreated per render) — a per-render
 * component identity would remount the whole canvas subtree on every
 * selection change.
 */
function StudioQuestionShell({
  question,
  index,
  siblingCount,
  hiddenByLogic,
  children,
}: QuestionShellProps) {
  const { t } = useTranslation();
  const studio = useStudioCanvas();

  const hiddenBadge = (
    <span className="pointer-events-none absolute -top-2.5 right-3 z-10 flex items-center gap-1 rounded bg-amber-100 px-2 py-0.5 text-[10px] font-semibold text-amber-800">
      <EyeOff className="size-3" />
      {t("hidden_by_conditions")}
    </span>
  );

  // Preview mode renders the plain form.
  if (!studio.editing) return <>{children}</>;

  const selected = studio.selectedId === question.id;

  const toolbarButton = (
    label: string,
    Icon: typeof ArrowUp,
    onClick: () => void,
    options?: { disabled?: boolean; destructive?: boolean },
  ) => (
    <button
      type="button"
      aria-label={label}
      title={label}
      disabled={options?.disabled}
      onClick={(event) => {
        event.stopPropagation();
        onClick();
      }}
      className={cn(
        "flex size-7 items-center justify-center rounded-md text-gray-500 transition-colors disabled:opacity-40",
        options?.destructive
          ? "hover:bg-red-50 hover:text-red-600"
          : "hover:bg-gray-100 hover:text-gray-900",
      )}
    >
      <Icon className="size-3.5" />
    </button>
  );

  return (
    // The inner form content is `inert` on the edit canvas, so this wrapper
    // is the click target; keyboard selection goes through the outline tree,
    // which lists every question as a real button.
    <div
      onClick={(event) => {
        event.stopPropagation();
        studio.onSelectQuestion(question.id);
      }}
      className={cn(
        "relative cursor-pointer rounded-xl transition-shadow",
        selected
          ? "ring-2 ring-primary-600 ring-offset-2"
          : "hover:ring-1 hover:ring-gray-300 hover:ring-offset-2",
      )}
    >
      {selected && (
        <>
          <span
            aria-hidden
            className="pointer-events-none absolute -top-2.5 left-3 z-10 rounded bg-primary-700 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide text-white"
          >
            {t("editing")}
          </span>
          <div className="absolute -top-4 right-3 z-10 flex items-center gap-0.5 rounded-lg border border-gray-200 bg-white p-0.5 shadow-md">
            {toolbarButton(
              t("move_question_up"),
              ArrowUp,
              () =>
                studio.dispatch({
                  type: "moveQuestion",
                  id: question.id,
                  direction: "up",
                }),
              { disabled: index === 0 },
            )}
            {toolbarButton(
              t("move_question_down"),
              ArrowDown,
              () =>
                studio.dispatch({
                  type: "moveQuestion",
                  id: question.id,
                  direction: "down",
                }),
              { disabled: index === siblingCount - 1 },
            )}
            <span aria-hidden className="mx-0.5 h-4 w-px bg-gray-200" />
            {toolbarButton(t("duplicate_question"), Copy, () =>
              studio.dispatch({ type: "duplicateQuestion", id: question.id }),
            )}
            {toolbarButton(
              t("delete_question"),
              Trash2,
              () =>
                studio.dispatch({
                  type: "removeQuestions",
                  ids: [question.id],
                }),
              { destructive: true },
            )}
          </div>
        </>
      )}
      {hiddenByLogic && !selected && hiddenBadge}
      {children}
    </div>
  );
}

function StudioAppendZone({ parentId }: { parentId: string | null }) {
  const { t } = useTranslation();
  const studio = useStudioCanvas();
  if (!studio.editing) return null;

  return (
    <button
      type="button"
      onClick={(event) => {
        event.stopPropagation();
        studio.dispatch({ type: "addQuestion", parentId });
      }}
      className="mt-3 flex w-full items-center justify-center gap-1.5 rounded-lg border border-dashed border-gray-300 bg-transparent py-2 text-xs font-semibold text-gray-500 hover:border-primary-500 hover:text-primary-700"
    >
      <Plus className="size-3.5" />
      {parentId ? t("add_question_here") : t("add_new_question")}
    </button>
  );
}

/**
 * In-flow chips under a question's label on the edit canvas: the
 * conditional-logic summary (reference design's "Shown when …" chip) and
 * any save-blocking issue for that question.
 */
function StudioQuestionAnnotation({ question }: { question: Question }) {
  const { t } = useTranslation();
  const studio = useStudioCanvas();
  if (!studio.editing) return null;

  const logicSummary = shortConditionSummary(
    question,
    studio.conditionTargets,
    t,
  );
  const issueKey = studio.issueKeysByQuestionId.get(question.id);
  if (!logicSummary && !issueKey) return null;

  return (
    <div className="flex flex-wrap items-center gap-1.5 pl-2.5">
      {logicSummary && (
        <span className="inline-flex items-center gap-1.5 rounded-md bg-amber-50 px-2 py-1 text-xs font-medium text-amber-800">
          <Split aria-hidden className="size-3 shrink-0" />
          {logicSummary}
        </span>
      )}
      {issueKey && (
        <span className="inline-flex items-center gap-1.5 rounded-md bg-red-50 px-2 py-1 text-xs font-medium text-red-700">
          <TriangleAlert aria-hidden className="size-3 shrink-0" />
          {t(issueKey)}
        </span>
      )}
    </div>
  );
}

const STUDIO_CHROME: FormChrome = {
  QuestionShell: StudioQuestionShell,
  AppendZone: StudioAppendZone,
  QuestionAnnotation: StudioQuestionAnnotation,
};

export interface StudioCanvasProps {
  editing: boolean;
  selectedId: string | null;
  onSelectQuestion: (id: string) => void;
  dispatch: Dispatch<BuilderAction>;
  questions: Question[];
  issueKeysByQuestionId: ReadonlyMap<string, string>;
  /** Bumped by outline/issue selection to scroll the question into view —
   *  canvas clicks don't scroll (the question is already on screen). */
  scrollRequest: { id: string; nonce: number } | null;
  emptyState?: React.ReactNode;
  headerHint?: React.ReactNode;
}

/** The center pane: the live form canvas with studio chrome. Must render
 *  inside the page's `QuestionnaireFormProvider`. */
export function StudioCanvas({
  editing,
  selectedId,
  onSelectQuestion,
  dispatch,
  questions,
  issueKeysByQuestionId,
  scrollRequest,
  emptyState,
  headerHint,
}: StudioCanvasProps) {
  const conditionTargets = useMemo(
    () => questionsByLinkId(questions),
    [questions],
  );

  useEffect(() => {
    if (!scrollRequest) return;
    // data-question-id is stamped by the form renderer itself, so this
    // works in both the decorated edit canvas and the plain preview.
    document
      .querySelector(`[data-question-id="${CSS.escape(scrollRequest.id)}"]`)
      ?.scrollIntoView({ behavior: "smooth", block: "center" });
  }, [scrollRequest]);

  return (
    <StudioCanvasContext.Provider
      value={{
        editing,
        selectedId,
        onSelectQuestion,
        dispatch,
        conditionTargets,
        issueKeysByQuestionId,
      }}
    >
      <QuestionnaireFormCanvas
        chrome={STUDIO_CHROME}
        emptyState={emptyState}
        headerHint={headerHint}
        // The edit canvas needs breathing room for the floating toolbar and
        // ring offsets.
        className={cn(editing && "px-1 pt-2")}
      />
    </StudioCanvasContext.Provider>
  );
}
