    handleFiltersChange({
      questionnaire: undefined,
      questionnaireTitle: undefined,
      createdBy: undefined,
      creatorName: undefined,
      status: undefined,
    });

  return {
    page,
    responseId,
    filters,
    hasFilters,
    updateParams,
    handleFiltersChange,
