import { expect, test, type Page } from "@playwright/test";
import {
  addTopLevelQuestion,
  adminApiHeaders,
  apiBaseUrl,
  createQuestionnaireAndOpenBuilder,
} from "tests/helper/questionnaireV2";
import {
  createFacilityOverride,
  deleteFacilityValueSetsBySlug,
  getInstanceValueSetIdBySlug,
} from "tests/helper/valueSet";
import { getFacilityId } from "tests/support/facilityId";

test.use({ storageState: "tests/.auth/user.json" });

// A different parent than the fill-side preference spec uses, so the two
// can run in parallel without racing on the per-facility slug constraint.
const PARENT_SLUG = "system-route";
const PARENT_NAME = "Route";
const ORAL_ROUTE = {
  system: "http://snomed.info/sct",
  version: null,
  concept: [{ code: "26643006", display: "Oral route" }],
};

/** Picks a question type by its cmdk data-value token. */
async function pickType(page: Page, type: string): Promise<void> {
  await page.getByRole("combobox").first().click();
  await page
    .locator(`[data-slot="command-item"][data-value="${type}"]`)
    .click();
}

interface StoredQuestion {
  text: string;
  answer_value_set?: { slug?: string | null; external_id?: string | null };
}

async function storedQuestion(
  questionnaireId: string,
  text: string,
): Promise<StoredQuestion> {
  const res = await fetch(
    `${apiBaseUrl()}/api/v1/questionnaire/${questionnaireId}/`,
    { headers: adminApiHeaders() },
  );
  const body = (await res.json()) as { questions: StoredQuestion[] };
  const question = body.questions.find((q) => q.text === text);
  if (!question) {
    throw new Error(`question "${text}" not found on ${questionnaireId}`);
  }
  return question;
}

/**
 * The studio's value-set picker inside a facility lists the facility's own
 * sets next to the instance ones, and stores them differently: an instance
 * set by slug alone (so the facility's override and each user's preference
 * apply at fill time), a facility set pinned by id.
 */
test.describe("Studio value-set picker (facility scope)", () => {
  test("labels both scopes and binds instance sets by slug, facility sets by id", async ({
    page,
  }) => {
    const facilityId = getFacilityId();
    const stamp = Date.now();
    const overrideName = `Route facility ${stamp}`;
    const questionTitle = `Route given ${stamp}`;

    await deleteFacilityValueSetsBySlug(facilityId, PARENT_SLUG);
    const overrideId = await createFacilityOverride({
      facilityId,
      parentId: await getInstanceValueSetIdBySlug(PARENT_SLUG),
      parentSlug: PARENT_SLUG,
      name: overrideName,
      include: ORAL_ROUTE,
    });

    try {
      let questionnaireId = "";

      await test.step("Author a value-set choice question", async () => {
        const detailUrl = await createQuestionnaireAndOpenBuilder(page, {
          basePath: `/facility/${facilityId}/settings/questionnaires`,
          title: `QV2 VS Scope ${stamp}`,
        });
        questionnaireId =
          detailUrl.match(/questionnaires\/([0-9a-f-]+)/)?.[1] ?? "";
        expect(questionnaireId).not.toBe("");

        await addTopLevelQuestion(page, questionTitle);
        await pickType(page, "choice");
        await page.getByRole("radio", { name: "Value Set" }).click();
      });

      await test.step("Picker lists the facility override and the instance set, labelled", async () => {
        await page
          .getByRole("combobox")
          .filter({ hasText: "Select a value set" })
          .click();
        const popover = page
          .locator("[data-radix-popper-content-wrapper]")
          .last();
        await popover
          .locator('[data-slot="command-input"]')
          .first()
          .fill("Route");
        await expect(
          popover.getByRole("option", {
            name: `${overrideName} (This facility)`,
          }),
        ).toBeVisible();
        await expect(
          popover.getByRole("option", { name: `${PARENT_NAME} (Instance)` }),
        ).toBeVisible();
        await popover
          .getByRole("option", { name: `${overrideName} (This facility)` })
          .click();
      });

      // Two saves happen seconds apart, so the first success toast can still
      // be on screen when the second Save is clicked — wait on the PUT itself.
      const saveChanges = async () => {
        const saved = page.waitForResponse(
          (res) =>
            res.request().method() === "PUT" &&
            res.url().includes(`/questionnaire/${questionnaireId}/`),
        );
        await page.getByRole("button", { name: "Save Changes" }).click();
        expect((await saved).ok()).toBe(true);
      };

      await test.step("A facility set is stored pinned by id", async () => {
        await saveChanges();
        const question = await storedQuestion(questionnaireId, questionTitle);
        expect(question.answer_value_set?.external_id).toBe(overrideId);
        expect(question.answer_value_set?.slug).toBe(PARENT_SLUG);
      });

      await test.step("An instance set is stored by slug alone", async () => {
        // The combobox now shows the current pick, not the placeholder the
        // shared helper keys on — re-pick through the labelled trigger.
        await page
          .getByRole("combobox")
          .filter({ hasText: `${overrideName} (This facility)` })
          .click();
        const popover = page
          .locator("[data-radix-popper-content-wrapper]")
          .last();
        await popover
          .locator('[data-slot="command-input"]')
          .first()
          .fill("Route");
        await popover
          .getByRole("option", { name: `${PARENT_NAME} (Instance)` })
          .click();
        await expect(
          page
            .getByRole("combobox")
            .filter({ hasText: `${PARENT_NAME} (Instance)` }),
        ).toBeVisible();
        await saveChanges();
        const question = await storedQuestion(questionnaireId, questionTitle);
        expect(question.answer_value_set?.slug).toBe(PARENT_SLUG);
        expect(question.answer_value_set?.external_id ?? null).toBeNull();
      });

      await test.step("Clearing a resolved set removes the binding and its displayed selection", async () => {
        const selectedTrigger = page
          .getByRole("combobox")
          .filter({ hasText: `${PARENT_NAME} (Instance)` });
        await selectedTrigger
          .locator("xpath=..")
          .getByRole("button", { name: "Clear", exact: true })
          .click();
        await expect(
          page.getByRole("combobox").filter({ hasText: "Select a value set" }),
        ).toBeVisible();
        await expect(selectedTrigger).toHaveCount(0);
import { Input } from "@/components/ui/input";
import { useState } from "react";

/** Keep in-progress numeric text local so a partial decimal is not rewritten
 * from the last committed number before the user finishes typing. */
export function NumericConditionInput({
  value,
  onChange,
  "aria-label": ariaLabel,
}: {
  value: string | number | boolean;
  onChange: (next: number) => void;
  "aria-label"?: string;
}) {
  const [buffer, setBuffer] = useState<string | null>(null);
  return (
    <Input
      type="number"
      aria-label={ariaLabel}
      value={buffer ?? String(value ?? "")}
      onChange={(e) => {
        setBuffer(e.target.value);
        if (e.target.value !== "" && !Number.isNaN(e.target.valueAsNumber)) {
          onChange(e.target.valueAsNumber);
        }
      }}
      onBlur={() => setBuffer(null)}
    />
  );
}
import careConfig from "@careConfig";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { AlertCircle } from "lucide-react";
import { ReactNode, useState } from "react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { cn } from "@/lib/utils";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";

import AvatarEditModal from "@/components/Common/AvatarEditModal";
import Loading from "@/components/Common/Loading";
import ErrorPage from "@/components/ErrorPages/DefaultErrorPage";

import useAuthUser from "@/hooks/useAuthUser";

import { getPermissions } from "@/common/Permissions";

import mutate from "@/Utils/request/mutate";
import query from "@/Utils/request/query";
import { usePermissions } from "@/context/PermissionContext";
import { FacilitySettingsOverview } from "@/pages/Facility/settings/general/FacilitySettingsOverview";
import facilityApi from "@/types/facility/facilityApi";

import { FacilityHomeActions } from "./FacilityHomeActions";
import { FacilityHomeOverview } from "./FacilityHomeOverview";

interface FacilityHomeProps {
  facilityId: string;
  appearance?: "default" | "settings";
  renderSettingsActions?: (disabled: boolean) => ReactNode;
}

const settingsButtonClassName =
  "h-12 border-neutral-400 text-sm text-neutral-950 shadow-md hover:bg-neutral-200/75 focus-visible:ring-0 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-500 md:h-10 [&_svg]:size-5";

export const FacilityHome = ({
  facilityId,
  appearance = "default",
  renderSettingsActions,
}: FacilityHomeProps) => {
  const isSettings = appearance === "settings";
  const { t } = useTranslation();
  const user = useAuthUser();
  const [editCoverImage, setEditCoverImage] = useState(false);
  const queryClient = useQueryClient();
  const { hasPermission } = usePermissions();

  const {
    data: facilityData,
    isLoading,
    isError,
    isFetching,
    refetch,
  } = useQuery({
    queryKey: ["facility", facilityId],
    queryFn: query(facilityApi.get, {
      pathParams: { facilityId },
    }),
  });

  const { canUpdateFacility } = getPermissions(
    hasPermission,
    facilityData?.root_org_permissions ?? [],
  );
  const { mutateAsync: deleteAvatar } = useMutation({
    mutationFn: mutate(facilityApi.deleteCoverImage, {
      pathParams: { facilityId },
    }),
    onSuccess: () => {
      toast.success(t("cover_image_deleted"));
      queryClient.invalidateQueries({
        queryKey: ["facility", facilityId],
      });
      setEditCoverImage(false);
    },
  });

  const { mutateAsync: uploadCoverImage } = useMutation({
    mutationFn: mutate(facilityApi.uploadCoverImage, {
      pathParams: { facilityId },
    }),
    onSuccess: () => {
      setEditCoverImage(false);
      queryClient.invalidateQueries({
        queryKey: ["facility", facilityId],
      });
      toast.success(t("cover_image_updated"));
    },
  });

  const handleCoverImageUpload = async (
    file: File,
    onSuccess: () => void,
    onError: () => void,
  ) => {
    try {
      const formData = new FormData();
      formData.append("cover_image", file);
      await uploadCoverImage(formData);
      onSuccess();
    } catch {
      onError();
    }
  };
  const handleCoverImageDelete = async (
    onSuccess: () => void,
    onError: () => void,
  ) => {
    try {
      await deleteAvatar();
      onSuccess();
    } catch {
      onError();
    }
  };

  if (isLoading) {
    return isSettings ? (
      <div role="status" className="space-y-6">
        <span className="sr-only">{t("loading")}</span>
        <div className="flex items-center gap-4 border-b border-neutral-200 pb-6">
          <Skeleton className="size-16 rounded-[10px]" />
          <div className="space-y-2">
            <Skeleton className="h-7 w-56 max-w-[60vw]" />
            <Skeleton className="h-4 w-32" />
          </div>
        </div>
        <div className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_20rem]">
          <Skeleton className="h-64 rounded-[10px]" />
          <Skeleton className="h-48 rounded-[10px]" />
        </div>
      </div>
    ) : (
      <Loading />
    );
  }

  const facilityError = (
    <Alert variant="destructive" className="mb-4">
      <AlertCircle />
      <AlertDescription>
        <p>
          {t(facilityData ? "facility_refresh_error" : "facility_load_error")}
        </p>
        <Button
          variant="outline"
          className={cn("mt-3", settingsButtonClassName)}
          disabled={isFetching}
          onClick={() => void refetch()}
        >
          {t("try_again")}
        </Button>
      </AlertDescription>
    </Alert>
  );

  if (isSettings && !facilityData) {
    return facilityError;
  }

  const coverImageHint = (
    <>
      {t("max_size_for_image_uploaded_should_be", {
        maxSize: `${careConfig.imageUploadMaxSizeInMB}MB`,
      })}
      <br />
      {t("allowed_formats_are", { formats: "jpg, png, jpeg" })}{" "}
      {t("recommended_aspect_ratio_for", { aspectRatio: "16:9" })}
    </>
  );

  if (!facilityData) {
    return <ErrorPage />;
  }

  const coverImageDialog = (
    <AvatarEditModal
      title={t("edit_cover_photo")}
      open={editCoverImage}
      imageUrl={facilityData?.read_cover_image_url}
      handleUpload={handleCoverImageUpload}
      handleDelete={handleCoverImageDelete}
      onOpenChange={(open) => setEditCoverImage(open)}
      hint={coverImageHint}
      aspectRatio={16 / 9}
    />
  );
  const facilityActions = canUpdateFacility ? (
    <FacilityHomeActions
      facility={facilityData}
      isSettings={isSettings}
      buttonClassName={isSettings ? settingsButtonClassName : undefined}
      onEditCoverImage={() => setEditCoverImage(true)}
    />
  ) : null;

  if (isSettings) {
    return (
      <>
        {coverImageDialog}
        {isError && facilityError}
        <FacilitySettingsOverview
          facility={facilityData}
          actions={facilityActions}
          settingsActions={renderSettingsActions?.(isError)}
          canDelete={user.is_superuser}
        />
      </>
    );
  }

  return (
    <div>
      {coverImageDialog}
      <FacilityHomeOverview
        facility={facilityData}
        actions={facilityActions}
        canUpdateFacility={canUpdateFacility}
        canDelete={user.is_superuser}
        onEditCoverImage={() => setEditCoverImage(true)}
      />
    </div>
  );
};

