                {isFetching ? t("importing") : t("import")}
              </Button>
            </>
          ) : (
            <>
              <Button
                type="button"
                variant="outline"
                onClick={() => setStep("select")}
              >
                {t("back")}
              </Button>
              <Button type="button" onClick={handleConfirm}>
                {t("import")}
              </Button>
            </>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

