  return (
    <div className="space-y-4 p-6">
      <Alert variant="destructive">
        <AlertTitle>{t("error")}</AlertTitle>
        <AlertDescription>{message}</AlertDescription>
      </Alert>
      <Button variant="outline" onClick={() => navigate(exitTarget)}>
        <ArrowLeft className="size-4" />
        {t("back")}
      </Button>
    </div>
  );
}
