import { useMutation, useQueryClient } from "@tanstack/react-query";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { questionnaireKeys } from "@/components/QuestionnaireV2/queryKeys";
import { useBatchRequest } from "@/Utils/request/batch";

import {
  QuestionnaireRead,
  QuestionnaireScope,
  QuestionnaireUpdate,
} from "@/types/questionnaire/questionnaire";
import questionnaireApi from "@/types/questionnaire/questionnaireApi";
import mutate from "@/Utils/request/mutate";

import type { OrganizationSelection } from "./OrganizationsField";

interface OrganizationUpdate extends OrganizationSelection {
  scope: QuestionnaireScope;
}

interface SaveVariables {
  body: QuestionnaireUpdate;
  organizations?: OrganizationUpdate;
  onCallSaved?: (updated: QuestionnaireRead) => void;
}

/** Metadata and pending organization access changes save atomically. */
export function useUpdateQuestionnaire(
  id: string,
  onSaved?: (updated: QuestionnaireRead) => void,
) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const batch = useBatchRequest({});

  const update = useMutation({
    mutationFn: async ({ body, organizations }: SaveVariables) => {
      if (!organizations) {
        return mutate(questionnaireApi.update, { pathParams: { id } })(body);
      }
      const facility = organizations.scope.authContext === "facility";
      const { results } = await batch.mutateAsync([
        {
          api: questionnaireApi.update,
          pathParams: { id },
          body,
          referenceId: "questionnaire",
        },
        {
          api: facility
            ? questionnaireApi.setFacilityOrganizations
            : questionnaireApi.setOrganizations,
          pathParams: { id },
          body: facility
            ? { facility_organizations: organizations.ids }
            : { organizations: organizations.ids },
          referenceId: "organizations",
        },
      ]);
      // The batch reference always contains the typed update response.
      return results.find((result) => result.reference_id === "questionnaire")
        ?.data as QuestionnaireRead;
    },
    onSuccess: async (updated, { organizations, onCallSaved }) => {
      queryClient.setQueryData(questionnaireKeys.detail(id), updated);
      if (organizations) {
        const facility = organizations.scope.authContext === "facility";
        const records = facility
          ? (organizations.facilityOrganizations ?? [])
          : organizations.organizations;
        // Seed the saved selection even if its picker is unmounted or the
        // following background refresh fails. Never restore stale access.
        if (
          records.length === organizations.ids.length &&
          records.every((record) => organizations.ids.includes(record.id))
        ) {
          queryClient.setQueryData(
            questionnaireKeys.organizations(
              id,
              facility ? "facility" : "instance",
            ),
            { count: records.length, results: records },
          );
        }
      }
      // Keep controls locked until the new baseline is available. Only then
      // may the page clear its pending selection and report a clean form.
      await queryClient.invalidateQueries({ queryKey: questionnaireKeys.all });
      toast.success(t("questionnaire_updated_successfully"));
      onSaved?.(updated);
      onCallSaved?.(updated);
    },
  });

  return {
    isPending: update.isPending,
    mutate: (
      body: QuestionnaireUpdate,
      organizations?: OrganizationUpdate,
    isLoading,
    isError,
  } = useQuery({
    queryKey: questionnaireKeys.organizations(questionnaireId, "instance"),
    // silent: cross-scope questionnaires 403 here on page load (see
    // OrganizationsUnavailableCard) — surfaced inline, not as a toast.
    queryFn: query(questionnaireApi.getOrganizations, {
      pathParams: { id: questionnaireId },
      silent: true,
    }),
  });

  const { data: available, isLoading: isSearching } = useQuery({
    queryKey: ["organizations", "role", searchQuery],
    queryFn: query.debounced(organizationApi.list, {
      queryParams: { org_type: "role", name: searchQuery || undefined },
    }),
    enabled: canWrite && !isError,
  });

  const selected = draft?.organizations ?? current?.results ?? [];

  if (isError) {
    return <OrganizationsUnavailableCard />;
  }

  const handleToggle = (orgId: string) => {
    const isSelected = selected.some((org) => org.id === orgId);
    let next: OrganizationSelection["organizations"];
    if (isSelected) {
      next = selected.filter((org) => org.id !== orgId);
    } else {
      const orgToAdd = [
        ...(current?.results ?? []),
        ...(available?.results ?? []),
      ].find((org) => org.id === orgId);
      next = orgToAdd ? [...selected, orgToAdd] : selected;
    }
    const ids = next.map((org) => org.id);
    const savedIds = current?.results.map((org) => org.id) ?? [];
    onChange(
      ids.length === savedIds.length && ids.every((id) => savedIds.includes(id))
        ? null
        : { ids, organizations: next },
    );
  };

  return (
    <OrganizationsFieldShell>
      {/* One control: the selected chips render inline inside the same
          bordered box as the search trigger, not in a separate dashed box. */}
      <div className="flex flex-wrap items-center gap-2 rounded-md border border-gray-200 p-1.5">
        {!isLoading && !canWrite && selected.length === 0 && (
          <p className="px-1.5 py-1 text-sm text-gray-500">
            {t("no_organizations_selected")}
          </p>
        )}
        {selected.map((org) => (
          <Badge key={org.id} variant="secondary" className="gap-1">
            {org.name}
            {canWrite && (
              <button
                type="button"
                onClick={() => handleToggle(org.id)}
                aria-label={t("remove_organization")}
              >
                <X className="size-3" />
              </button>
            )}
          </Badge>
        ))}
          ))}
        </div>
      </OrganizationsFieldShell>
    );
  }

  return (
    <OrganizationsFieldShell>
      {!isLoading && (
        <FacilityOrganizationSelector
          facilityId={facilityId}
          value={currentIds}
          currentOrganizations={
            draft?.facilityOrganizations ?? current?.results
          }
          optional
          onChange={(value, facilityOrganizations) => {
            const ids = value ?? [];
            const savedIds = current?.results.map((org) => org.id) ?? [];
            onChange(
              ids.length === savedIds.length &&
                ids.every((id) => savedIds.includes(id))
                ? null
                : { ids, organizations: [], facilityOrganizations },
            );
          }}
        />
      )}
    </OrganizationsFieldShell>
  );
}

