import { zodResolver } from "@hookform/resolvers/zod";
import {
  useEffect,
  useEffectEvent,
  useMemo,
  useReducer,
  useRef,
  useState,
} from "react";
import { useForm, useWatch } from "react-hook-form";
import { useTranslation } from "react-i18next";

import {
  BuilderState,
  builderReducer,
} from "@/components/QuestionnaireV2/builder/builderReducer";
import type { OrganizationSelection } from "@/components/QuestionnaireV2/manage/OrganizationsField";
import {
  DetailFormValues,
  questionnaireBasicSchema,
} from "@/components/QuestionnaireV2/manage/questionnaireFormSchema";
import { useUpdateQuestionnaire } from "@/components/QuestionnaireV2/manage/useUpdateQuestionnaire";
import { buildUpdateBody } from "@/components/QuestionnaireV2/shared/buildUpdateBody";
import { normalizeQuestionnaireActions } from "@/types/questionnaire/actions";
import {
  QuestionnaireRead,
  QuestionnaireScope,
} from "@/types/questionnaire/questionnaire";

const INITIAL_STATE: BuilderState = {
  questions: [],
  actions: [],
  selectedId: null,
  dirty: false,
};

function metadataValues(questionnaire: QuestionnaireRead): DetailFormValues {
  return {
    title: questionnaire.title,
    slug: questionnaire.slug,
    description: questionnaire.description ?? "",
    status: questionnaire.status,
  };
}

function metadataMatches(a: DetailFormValues, b: DetailFormValues) {
  return (
    a.title === b.title &&
    a.slug === b.slug &&
    a.description === b.description &&
    a.status === b.status
  );
}

interface UseStudioDraftOptions {
  id: string;
  scope: QuestionnaireScope;
  questionnaire: QuestionnaireRead | undefined;
}

/** Owns the editable question tree, metadata and access changes together
 * with their save/discard lifecycle. Display selection and validation remain
 * outside this hook; only a validated submission calls saveDraft. */
export function useStudioDraft({
  id,
  scope,
  questionnaire,
}: UseStudioDraftOptions) {
  const { t } = useTranslation();
  const [state, reactDispatch] = useReducer(builderReducer, INITIAL_STATE);
  // Resets come from the server or Discard. Every other dispatch counts so
  // an in-flight save cannot overwrite a newer edit or selection.
  const dispatchSeqRef = useRef(0);
  const dispatch: typeof reactDispatch = (action) => {
    if (action.type !== "reset") dispatchSeqRef.current += 1;
    reactDispatch(action);
  };

  const loadQuestionnaire = useEffectEvent((loaded: QuestionnaireRead) => {
    if (state.dirty) return;
    dispatch({
      type: "reset",
      questions: loaded.questions,
      actions: normalizeQuestionnaireActions(loaded.actions),
      keepSelectedId: state.selectedId,
    });
  });
  useEffect(() => {
    // Refetches refresh a clean draft, but never discard unsaved questions.
    // Read the current dirty/selection state without re-seeding on edits.
    if (questionnaire) loadQuestionnaire(questionnaire);
  }, [questionnaire]);

  const metaSchema = useMemo(() => questionnaireBasicSchema(t), [t]);
  const form = useForm<DetailFormValues>({
    resolver: zodResolver(metaSchema),
    values: questionnaire ? metadataValues(questionnaire) : undefined,
    resetOptions: { keepDirtyValues: true },
  });
  const [organizationDraft, setOrganizationDraft] =
    useState<OrganizationSelection | null>(null);
  const dirty =
    state.dirty || form.formState.isDirty || organizationDraft !== null;

  const [metaTitle, metaDescription] = useWatch({
    control: form.control,
    name: ["title", "description"],
  });
  // The preview provider merges responses when this identity changes, so
  // edits can refresh the canvas without clearing its entered responses.
  const draft = useMemo(
    () =>
      questionnaire
        ? {
            ...questionnaire,
            title: metaTitle || questionnaire.title,
            description: metaDescription ?? questionnaire.description,
            questions: state.questions,
          }
        : undefined,
    [questionnaire, state.questions, metaTitle, metaDescription],
  );

  const saveDispatchSeqRef = useRef(0);
  const saveMetaRef = useRef<DetailFormValues | null>(null);
  const savedOrganizationsRef = useRef<OrganizationSelection | null>(null);
  const { mutate: save, isPending } = useUpdateQuestionnaire(id, (updated) => {
    const questionsEditedDuringFlight =
      dispatchSeqRef.current !== saveDispatchSeqRef.current;
    // isDirty alone cannot detect a second edit to an already-dirty field.
    // Compare the submitted metadata to live values before resetting it.
    const metaEditedDuringFlight =
      !saveMetaRef.current ||
      !metadataMatches(saveMetaRef.current, form.getValues());

    // Each draft part resets independently. The mutation has already updated
    // the query cache, so revision badges advance even if newer edits remain.
    if (!questionsEditedDuringFlight) {
      dispatch({
        type: "reset",
        questions: updated.questions,
        actions: normalizeQuestionnaireActions(updated.actions),
        keepSelectedId: state.selectedId,
      });
    }
    setOrganizationDraft((current) =>
      current === savedOrganizationsRef.current ? null : current,
    );
    if (!metaEditedDuringFlight) form.reset(metadataValues(updated));
  });

  const saveDraft = (meta: DetailFormValues) => {
    if (!questionnaire) return;
    // Capture exactly what this PUT includes; the response may arrive after
    // the author has continued editing any of these three draft parts.
    saveDispatchSeqRef.current = dispatchSeqRef.current;
    saveMetaRef.current = meta;
    savedOrganizationsRef.current = organizationDraft;
    save(
      buildUpdateBody(questionnaire, {
        questions: state.questions,
        actions: state.actions,
        title: meta.title,
        slug: meta.slug,
        description: meta.description,
        status: meta.status,
      }),
      organizationDraft ? { scope, ...organizationDraft } : undefined,
    );
  };

  const discardDraft = () => {
    if (!questionnaire) return;
    setOrganizationDraft(null);
    dispatch({
      type: "reset",
      questions: questionnaire.questions,
      actions: normalizeQuestionnaireActions(questionnaire.actions),
      keepSelectedId: state.selectedId,
    });
    form.reset(metadataValues(questionnaire));
  };

  return {
    state,
    dispatch,
    form,
    draft,
    organizationDraft,
    setOrganizationDraft,
    dirty,
    isPending,
    saveDraft,
    discardDraft,
  };
}
import { Dispatch, useState } from "react";

import {
  BuilderAction,
  BuilderState,
  findQuestion,
} from "@/components/QuestionnaireV2/builder/builderReducer";
import {
  findQuestionNumber,
  findTopLevelIndex,
} from "@/components/QuestionnaireV2/shared/questionTree";

/** Inspector and reveal state, kept separate from the persisted draft. The
 * outline owns its keyboard/multi-selection behavior and calls these actions. */
export function useStudioSelection(
  state: BuilderState,
  dispatch: Dispatch<BuilderAction>,
) {
  const [inspectorTarget, setInspectorTarget] = useState<
    "form" | "question" | "actions"
  >("question");
  // The expanded card in the Actions panel — owned here so an issue click
  // from the top bar can open the right one.
  const [openActionIndex, setOpenActionIndex] = useState<number | null>(null);
  const [scrollRequest, setScrollRequest] = useState<{
    id: string;
    nonce: number;
  } | null>(null);
  // Creating or importing questions selects them in the reducer — the
  // inspector must follow, or it would stay on Form settings showing
  // nothing about the question that just appeared.
  const studioDispatch: typeof dispatch = (action) => {
    if (
      action.type === "addQuestion" ||
      action.type === "duplicateQuestion" ||
      action.type === "replaceAll"
    ) {
      setInspectorTarget("question");
    }
    dispatch(action);
  };

  const selectQuestion = (questionId: string) => {
    dispatch({ type: "select", id: questionId });
    setInspectorTarget("question");
  };

  const revealQuestion = (questionId: string) => {
    selectQuestion(questionId);
    setScrollRequest((previous) => ({
      id: questionId,
      nonce: (previous?.nonce ?? 0) + 1,
    }));
  };

  const revealAction = (index: number) => {
    setInspectorTarget("actions");
    setOpenActionIndex(index);
  };

  const selectedQuestion = state.selectedId
    ? findQuestion(state.questions, state.selectedId)
    : undefined;
  // Which inspector shows: Actions when asked for; otherwise Form settings
  // stands in whenever no question is selected.
  const panel: "form" | "question" | "actions" =
    inspectorTarget === "actions"
      ? "actions"
      : inspectorTarget === "form" || !selectedQuestion
        ? "form"
        : "question";
  const formSelected = panel === "form";
  const topLevelIndex = state.selectedId
    ? findTopLevelIndex(state.questions, state.selectedId)
    : 0;
  // The selected question's own dotted number (e.g. "3.1." for a nested
  // child) — falls back to the top-level ancestor's ordinal for questions
  // nested deeper than `findQuestionNumber` numbers (grandchildren+).
  const selectedNumber =
    (state.selectedId &&
      findQuestionNumber(state.questions, state.selectedId)) ||
    `${topLevelIndex + 1}.`;
  return {
    studioDispatch,
    setInspectorTarget,
    openActionIndex,
    setOpenActionIndex,
    scrollRequest,
    selectQuestion,
    revealQuestion,
    revealAction,
    selectedQuestion,
    selectedNumber,
    panel,
    formSelected,
  };
}
import { useDeferredValue, useMemo, useSyncExternalStore } from "react";

import { findActionIssues } from "@/components/QuestionnaireV2/builder/actionValidation";
import { reachableContextPaths } from "@/components/QuestionnaireV2/builder/actionVariables";
import { useActionRegistry } from "@/components/QuestionnaireV2/builder/actions/useActionRegistry";
import { findInvalidQuestions } from "@/components/QuestionnaireV2/builder/saveValidation";
import { actionReferencedLinkIds } from "@/components/QuestionnaireV2/shared/actionExpression";
import {
  getStructuredTypesVersion,
  subscribeToStructuredTypes,
} from "@/components/QuestionnaireV2/structured/pluginRegistry";
import {
  actionContextTypeFor,
  QuestionnaireAction,
} from "@/types/questionnaire/actions";
import { Question } from "@/types/questionnaire/question";
import { SubjectType } from "@/types/questionnaire/questionnaire";

interface UseStudioIssuesOptions {
  questions: Question[];
  actions: QuestionnaireAction[];
  subjectType: SubjectType | undefined;
}

/** Deferred validation for outline/canvas warnings and issue navigation.
 * Save still checks the live question tree, independently of this display. */
export function useStudioIssues({
  questions,
  actions,
  subjectType,
}: UseStudioIssuesOptions) {
  // The unknown-structured-type rule reads the plugin registry, which fills
  // in only after the federation manifests resolve — later than the first
  // render of a cold-loaded questionnaire. Without re-running on that, a
  // plugin-typed question would show false "Unknown structured type"
  // warnings (outline icons, canvas chips, issues popover) until an edit
  // happened to invalidate the memo.
  const structuredTypesVersion = useSyncExternalStore(
    subscribeToStructuredTypes,
    getStructuredTypesVersion,
    getStructuredTypesVersion,
  );
  // Deferring the tree keeps typing responsive while warning displays catch
  // up. The page's save handler checks the live tree synchronously instead.
  const deferredQuestions = useDeferredValue(questions);
  const issues = useMemo(() => {
    // Referenced so the dependency is a real read, not one exhaustive-deps
    // would call spurious: the registry lookup happens inside
    // `findInvalidQuestions`, where the rule cannot see it.
    void structuredTypesVersion;
    return findInvalidQuestions(deferredQuestions);
  }, [deferredQuestions, structuredTypesVersion]);
  // First failing rule per question — powers the outline warning icons and
  // the canvas error chips alongside the top bar's popover.
  const issueKeysByQuestionId = useMemo(
    () =>
      new Map(
        issues.map(({ question, messageKey }) => [question.id, messageKey]),
      ),
    [issues],
  );

  // What the backend can run and what an action may read; the actions'
  // own save rules ride the same deferred tree as the question rules.
  const registry = useActionRegistry();
  const contextPaths = useMemo(() => {
    if (registry.isLoading || registry.isError) return undefined;
    const rootType = subjectType && actionContextTypeFor(subjectType);
    return rootType ? reachableContextPaths(rootType, registry.fields) : [];
  }, [subjectType, registry.fields, registry.isLoading, registry.isError]);
  const actionIssues = useMemo(
    () =>
      findActionIssues(actions, {
        questions: deferredQuestions,
        instructions: registry.instructions,
        contextPaths,
      }),
    [actions, deferredQuestions, registry.instructions, contextPaths],
  );
  // Questions an action reads — the outline marks them so an author
  // retitling or deleting one knows something depends on it.
  const actionLinkIds = useMemo(
    () => new Set(actions.flatMap(actionReferencedLinkIds)),
    [actions],
  );

  return {
    issues,
    issueKeysByQuestionId,
    registry,
    contextPaths,
    actionIssues,
    actionLinkIds,
  };
}

