  const readLocalDraft = () =>
    scopeKey && scope && questionnaire && !continueDraftId
      ? loadFillDraft(scope, questionnaire.questions)
      : undefined;
  const [snapshot, setSnapshot] = useState(() => ({
    sessionKey,
    draft: readLocalDraft(),
