/** Resolve draft recovery for a session without rereading autosaved edits on refetch. */
export function useFillPageDrafts({
  subject,
  questionnaire,
  continueDraftId,
  serverDraft,
  resumeLocalDraft,
  prescription,
  toDischarge,
}: FillPageDraftsOptions) {
