    sessionKey,
    draft: readLocalDraft(),
  }));
  let localDraft = snapshot.draft;
  if (snapshot.sessionKey !== sessionKey) {
    localDraft = readLocalDraft();
    setSnapshot({ sessionKey, draft: localDraft });
  }

  return { scope, sessionKey, localDraft, serverDraftState };
